// FIX: Replaced old Build Exam List + separate Identify Gaps with a single node.
// Now uses EXPECTED_EXAMS to catch exams missing from chroma_db_stats entirely.
// Outputs a single item with has_gaps flag + arrays for branching.
const status = $input.first().json;
const stats = status.chroma_db_stats || {};
const EXPECTED_EXAMS = ['AI-102', 'AZ-104', 'AZ-305', 'GH-300', 'AB-100', 'AI-103', 'AI-901'];

const needsIndex = [];
const healthy = [];

for (const exam of EXPECTED_EXAMS) {
  const count = stats[exam] !== undefined ? stats[exam] :
                stats[exam.toLowerCase()] !== undefined ? stats[exam.toLowerCase()] : -1;
  if (count <= 0) {
    needsIndex.push({
      exam_code: exam,
      needs_index: true,
      current_chunks: Math.max(0, count),
      issue: count < 0 ? 'MISSING_FROM_STATS' : 'EMPTY'
    });
  } else {
    healthy.push({ exam_code: exam, needs_index: false, current_chunks: count });
  }
}

console.log('Needs indexing: ' + (needsIndex.map(i => i.exam_code).join(', ') || 'none'));
console.log('Healthy: ' + (healthy.map(i => i.exam_code + '(' + i.current_chunks + ')').join(', ') || 'none'));

return [{
  json: {
    needs_index: needsIndex,
    healthy,
    has_gaps: needsIndex.length > 0,
    gap_count: needsIndex.length,
    checked_at: new Date().toISOString()
  }
}];

// Extract the needs_index array and emit one item per failing exam.
// These feed into the splitInBatches loop below.
const data = $input.first().json;
return data.needs_index.map(exam => ({ json: exam }));

// Check the re-index result and log. Then loop back to splitInBatches.
const result = $input.first().json;
const exam = $('Process Gaps One at a Time').first().json.exam_code;
const r = (result.results && result.results[exam]) || {};

if (r.status && r.status === 'success') {
  console.log('[WF1 Auto-fix] ' + exam + ': SUCCESS — ' + (r.chunks_indexed || 0) + ' chunks indexed');
} else {
  console.error('[WF1 Auto-fix] ' + exam + ': FAILED — ' + (r.reason || 'check backend logs'));
}

return [{ json: { exam_code: exam, status: r.status || 'unknown', chunks_indexed: r.chunks_indexed || 0, reason: r.reason || null } }];

const data = $input.first().json;
console.log('[WF1] All exams healthy — ' + data.healthy.length + ' exams OK, checked at ' + data.checked_at);
return [{ json: { status: 'healthy', exam_count: data.healthy.length, checked_at: data.checked_at } }];
